#!/usr/bin/env node
/**
 * CLI-only startup boundary: reserve stderr when stdout carries machine output, then materialize
 * normal auth and the local personal credential only for protected commands. The MCP server never
 * imports this module, so it remains keyring-free and keeps full stderr diagnostics.
 */
import { materializeAuth } from "../api/auth-resolver.js";
import { CommanderError } from "commander";
import { setStderrLogging } from "../logging.js";
import { materializeCliPersonalBearerCredential } from "./auth/personal-bearer-credential.js";
import { commandNeedsMaterializedAuth } from "./auth/startup-auth.js";
import { cliMachineOutputSelected } from "./output-mode.js";
import { GENERATED_OPENAPI_COMMAND_SPECS } from "./generated/openapi-commands.js";

// `logging.ts` seeds this from the explicit flags alone; a piped stdout selects the same JSON
// payload without one, and that consumer needs the same quiet stderr.
if (cliMachineOutputSelected(process.argv.slice(2))) setStderrLogging(false);

try {
  if (commandNeedsMaterializedAuth(process.argv.slice(2), GENERATED_OPENAPI_COMMAND_SPECS)) {
    await materializeAuth();
    await materializeCliPersonalBearerCredential();
  }
  await import("./index.js");
} catch (failure) {
  if (!(failure instanceof CommanderError)) throw failure;
  process.stderr.write(`${failure.message}\n`);
  process.exitCode = failure.exitCode;
}
